/**
 * The types `knowledge/compartments/` exports, in one place — so a neighbouring module finds the shape it
 * needs here instead of declaring its own under a second name.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    BotPlusAbility, GuardianTrack, AcronymExpansion
 * depends    —
 * used by    src/knowledge/compartments/bots, src/knowledge/compartments/guardian, src/knowledge/compartments/naming
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */

// from bots.ts

/**
 * Bot+ abilities, one per bot, and they are NOT built to a common pattern.
 *
 * Four of the five run a 26-entry ladder stepping 50 medals — 0, 100, 150, 200
 * — and three of those four stop levelling at 20, leaving five entries unused.
 * Amplify Bot's Echoing Shot is a different thing entirely: ten entries
 * stepping 200, nine levels, and a top level costing 1700 where the others cost
 * 1300.
 *
 * So "Bot+ works like this" is true four times out of five, which is exactly the
 * ratio that gets a shared code path written and shipped.
 */
export type BotPlusAbility = {
  readonly bot: string
  readonly ability: string
  readonly maxLevel: number
  readonly costEntries: number
  readonly costStep: number
  readonly topCost: number
}

// from guardian.ts

export type GuardianTrack = {
  readonly chip: string
  readonly track: string
  readonly maxLevel: number
  readonly totalCost: number
}

// from naming.ts

export interface AcronymExpansion {
  /** What the acronym means, spelled canonically. */
  meaning: string
  /** The graph entity it names, when there is one. */
  entityId?: string
  /** Why this reading rather than another — only where the acronym is ambiguous. */
  whenToUse?: string
}
